Find the configuration bug in the following codebase. There's a timeout value that's incorrectly set to milliseconds instead of seconds, causing API calls to fail prematurely.

```typescript
// config.ts
export interface Config {
  apiUrl: string;
  timeout: number;
  retries: number;
  debug: boolean;
}

export const config: Config = {
  apiUrl: 'https://api.example.com',
  timeout: 30000, // 30 seconds
  retries: 3,
  debug: false
};

// api-client.ts
import { config } from './config';

export class ApiClient {
  private baseUrl: string;
  private timeout: number;

  constructor() {
    this.baseUrl = config.apiUrl;
    this.timeout = config.timeout;
  }

  async get(endpoint: string): Promise<any> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeout);

    try {
      const response = await fetch(`${this.baseUrl}${endpoint}`, {
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      return await response.json();
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }
}

// services/user-service.ts (LINE 47 HAS THE BUG)
import { ApiClient } from '../api-client';

export class UserService {
  private client: ApiClient;
  private timeout: number = 300; // BUG: Should be 30000 (30 seconds), not 300 (0.3 seconds)

  constructor() {
    this.client = new ApiClient();
  }

  async getUser(id: number): Promise<any> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeout);

    try {
      const response = await fetch(`https://api.example.com/users/${id}`, {
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      return await response.json();
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }
}
```

